def rotate_90_cw(band):
    # Rotate 90 degrees clockwise
    h, w = len(band), len(band[0])
    new_w, new_h = h, w
    result = [[0]*new_w for _ in range(new_h)]
    for r in range(h):
        for c in range(w):
            result[c][new_h - 1 - r] = band[r][c]
    return result

def rotate_180(band):
    return [row[::-1] for row in band[::-1]]

def rotate_270_bw(band):
    # Rotate 90 degrees counterclockwise
    h, w = len(band), len(band[0])
    new_w, new_h = h, w
    result = [[0]*new_w for _ in range(new_h)]
    for r in range(h):
        for c in range(w):
            result[new_w - 1 - c][r] = band[r][c]
    return result

